SELECT CAST(REPLACE(REPLACE(REPLACE(employee_severance, '$', ''), ',', ''), ' ', '') AS REAL) / NULLIF((SELECT CAST(REPLACE(REPLACE(REPLACE(total, '$', ''), ',', ''), ' ', '') AS REAL) FROM table_228 WHERE item_name = 'Balance as of September 30, 2005'), 0) AS termination_rate
FROM table_228
WHERE item_name = 'Balance as of September 30, 2005';

SELECT CAST(REPLACE(REPLACE(REPLACE(mainline_operations, '$', ''), ',', ''), ' ', '') AS REAL) / NULLIF((SELECT CAST(REPLACE(REPLACE(REPLACE(total, '$', ''), ',', ''), ' ', '') AS REAL) FROM table_457 WHERE item_name = 'Total'), 0) AS pilots_and_flight_crew_portion_ratio
FROM table_457
WHERE item_name = 'Pilots and Flight Crew Training Instructors';
